mapper.select:
select sysMenu.*, sysLanguage.field_value as name from sys_role_user sysRoleUser inner join sys_role_menu sysRoleMenu on sysRoleUser.role_id = sysRoleMenu.role_id and sysRoleMenu.logical_delete = 0 inner join sys_menu sysMenu on sysRoleMenu.menu_id = sysMenu.id and sysMenu.logical_delete = 0 left join sys_language sysLanguage on sysLanguage.table_id = sysMenu.id and sysLanguage.table_name='sys_menu' and sysLanguage.field_name='name' and sysLanguage.language=#{language} and sysLanguage.logical_delete = 0 where sysRoleUser.logical_delete = 0 and sysRoleUser.user_id = #{userId}
and sysMenu.menu_type in
#{type}
order by sysMenu.sort asc
